insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in public institutions, as described in a committee meeting in a coastal academic seminar context.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','The decline in complaints was sudden and easy to explain.','Managers ignored the decline because it was caused by one change.','Managers blamed a single change because complaints rose quickly.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_18", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability during periods of change, as described in a student guide in a urban academic seminar context.','The writer discusses reliability without mentioning popularity.','The writer points out a difference between being popular now and being dependable over time.','The writer argues that long-term reliability is impossible.','The writer says popularity and reliability are exactly the same.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_18", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although classroom debates was initially criticized, later evidence showed that it could be useful when applied carefully in small communities, as described in a pilot study.','Early criticism proved that classroom debates had no value at all.','Later evidence showed that classroom debates should never be applied.','Later evidence suggested that classroom debates, despite early criticism, may have value if used carefully.','The usefulness of classroom debates was accepted before anyone criticized it.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_18", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The report does not claim that group projects solves every problem; it argues only that it can reduce one specific difficulty when resources are limited, as described in a professional workshop.','The report rejects the idea that group projects can help in any way.','The report discusses many solutions but never mentions a specific problem.','The report argues that group projects solves all problems completely.','According to the report, group projects is not a complete solution but may help with a particular problem.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_18", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion under careful supervision, as described in a policy review in a central academic seminar context.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers postponed collecting data after reaching a firm conclusion.','The available data forced the researchers to reject all conclusions.','The researchers made a recommendation because the data were complete.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_18", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes after initial trials, as described in a classroom discussion in a online academic seminar context.','The author claims feedback is useful only when students stop practicing.','The author believes practice works best if learners are told what they did wrong.','The author believes mistakes should be ignored during practice.','The author suggests that practice and feedback are unrelated.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_18", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in schools, as described in a research summary in a evening academic seminar context.','The new system was rejected because it was not transparent.','The new system was adopted mainly because it reduced costs.','The main reason for adopting the new system was improved transparency rather than lower cost.','The process became less transparent after the new system was adopted.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_18", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Even though the experiment was small, its results raised important questions for future research for adult learners, as described in a public debate in a summer academic seminar context.','The experiment was too large to raise useful questions.','Future research became unnecessary after the experiment.','The results were ignored because the experiment was not small.','Despite its limited size, the experiment produced results that future studies should examine.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_18", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction in public institutions, as described in a training program in a advanced academic seminar context.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage says convenience always guarantees satisfaction.','The passage denies that convenience affects service use.','The passage argues that inconvenient services attract the most users.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_18", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
