insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The writer contrasts short-term popularity with long-term reliability when resources are limited, as described in a policy review in a advanced community college context.','The writer points out a difference between being popular now and being dependable over time.','The writer argues that long-term reliability is impossible.','The writer says popularity and reliability are exactly the same.','The writer discusses reliability without mentioning popularity.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_21", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although group projects was initially criticized, later evidence showed that it could be useful when applied carefully under careful supervision, as described in a classroom discussion.','Later evidence showed that group projects should never be applied.','Later evidence suggested that group projects, despite early criticism, may have value if used carefully.','The usefulness of group projects was accepted before anyone criticized it.','Early criticism proved that group projects had no value at all.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_21", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that AI writing tools solves every problem; it argues only that it can reduce one specific difficulty after initial trials, as described in a research summary.','The report rejects the idea that AI writing tools can help in any way.','The report argues that AI writing tools solves all problems completely.','According to the report, AI writing tools is not a complete solution but may help with a particular problem.','The report discusses many solutions but never mentions a specific problem.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_21", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in schools, as described in a public debate.','The available data forced the researchers to reject all conclusions.','The researchers made a recommendation because the data were complete.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_21", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes for adult learners, as described in a training program.','The author believes practice works best if learners are told what they did wrong.','The author claims feedback is useful only when students stop practicing.','The author suggests that practice and feedback are unrelated.','The author believes mistakes should be ignored during practice.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_21", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
